1	"use client";
2	
3	// Real Gemini Live voice engine over a DIRECT browser→Google WebSocket.
4	//
5	// Architecture (no relay server, mirrors use-xai-session): mint a single-use
6	// ephemeral auth token at /api/gemini/token, then open the v1alpha
7	// `BidiGenerateContentConstrained` WebSocket with `?access_token=REDACTED
8	// (ephemeral tokens are v1alpha-only; the raw-key v1beta endpoint would expose
9	// GEMINI_API_KEY). We own the whole audio pipeline: mic → PCM16 →
10	// `realtimeInput.audio`; inbound `serverContent.modelTurn` inlineData → PCM16 →
11	// AudioBuffer playback. Barge-in is server-VAD driven (`serverContent.interrupted`
12	// → stop playback).
13	//
14	// Protocol differences from the OpenAI/xAI dialect that shape this file:
15	//  - One server message can carry SEVERAL fields at once (audio + transcription
16	//    + turnComplete) — every field is checked independently, never else-if.
17	//  - Input audio declares its true rate in the MIME type and Google resamples;
18	//    output audio is FIXED at 24 kHz, so PlaybackQueue gets an explicit rate.
19	//  - Transcripts stream as inputTranscription/outputTranscription fragments,
20	//    not as discrete conversation items.
21	//
22	// Exposes the same surface as useXaiSession so useRealtimeSession can dispatch
23	// to either engine uniformly. Must be called unconditionally (rules of hooks);
24	// it stays inert until start().
25	
26	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
27	import type { Persona } from "@/lib/data";
28	import type { CallState, SessionTurn } from "./types";
29	import { createMicCapture, type MicCapture } from "./mic-capture";
30	import { resolveGeminiAgent } from "./gemini-agent";
31	import {
32	  base64Pcm16ToFloat32,
33	  calculateRms,
34	  EarlyAudioBuffer,
35	  float32ToPcm16Base64,
36	  PlaybackQueue,
37	} from "./xai-audio";
38	
39	const REALTIME_URL =
40	  "wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1alpha.GenerativeService.BidiGenerateContentConstrained";
41	// Gemini Live always emits 24 kHz PCM16 regardless of the input rate.
42	const OUTPUT_RATE = 24_000;
43	const CHUNK_MS = 100;
44	const VOL_GAIN = 3.5;
45	
46	export interface GeminiSession {
47	  callState: CallState;
48	  turns: SessionTurn[];
49	  caption: string;
50	  start: () => void;
51	  stop: () => void;
52	  interrupt: () => void;
53	  setMuted: (muted: boolean) => void;
54	  getInputVolume: () => number;
55	  getOutputVolume: () => number;
56	}
57	
58	type GeminiServerMessage = {
59	  setupComplete?: Record<string, unknown>;
60	  serverContent?: {
61	    modelTurn?: { parts?: Array<{ inlineData?: { data?: string }; text?: string }> };
62	    inputTranscription?: { text?: string };
63	    outputTranscription?: { text?: string };
64	    interrupted?: boolean;
65	    generationComplete?: boolean;
66	    turnComplete?: boolean;
67	  };
68	  goAway?: { timeLeft?: string };
69	};
70	
71	export function useGeminiSession(active: boolean, persona?: Persona): GeminiSession {
72	  const [callState, setCallState] = useState<CallState>("idle");
73	  const [turns, setTurns] = useState<SessionTurn[]>([]);
74	  const [caption, setCaption] = useState("press CALL to begin");
75	
76	  const wsRef = useRef<WebSocket | null>(null);
77	  const ctxRef = useRef<AudioContext | null>(null);
78	  const streamRef = useRef<MediaStream | null>(null);
79	  const captureRef = useRef<MicCapture | null>(null);
80	  const playbackRef = useRef<PlaybackQueue | null>(null);
81	  // Early mic audio captured before setupComplete (parallel init).
82	  const earlyBufRef = useRef<EarlyAudioBuffer | null>(null);
83	  // True once `setupComplete` arrives: append chunks stream live; until then
84	  // they accumulate in earlyBufRef.
85	  const streamingRef = useRef(false);
86	
87	  const mutedRef = useRef(false);
88	  const endedRef = useRef(false);
89	  const inputRmsRef = useRef(0);
90	  const turnSeqRef = useRef(0);
91	  const agentTurnIdRef = useRef<string | null>(null);
92	  const agentBufRef = useRef("");
93	  const userTurnIdRef = useRef<string | null>(null);
94	  const userBufRef = useRef("");
95	  const interruptTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
96	  const stateRef = useRef<CallState>("idle");
97	  stateRef.current = callState;
98	  // Latest selected persona, read at start() time (avoids stale closures).
99	  const personaRef = useRef(persona);
100	  personaRef.current = persona;
101	
102	  const teardown = useCallback(() => {
103	    if (interruptTimerRef.current) {
104	      clearTimeout(interruptTimerRef.current);
105	      interruptTimerRef.current = null;
106	    }
107	    if (captureRef.current) {
108	      captureRef.current.stop();
109	      captureRef.current = null;
110	    }
111	    if (streamRef.current) {
112	      streamRef.current.getTracks().forEach((t) => t.stop());
113	      streamRef.current = null;
114	    }
115	    if (playbackRef.current) {
116	      playbackRef.current.stop();
117	      playbackRef.current = null;
118	    }
119	    if (wsRef.current) {
120	      try {
121	        wsRef.current.close();
122	      } catch {
123	        // already closing
124	      }
125	      wsRef.current = null;
126	    }
127	    if (ctxRef.current) {
128	      void ctxRef.current.close();
129	      ctxRef.current = null;
130	    }
131	    streamingRef.current = false;
132	    earlyBufRef.current = null;
133	    agentTurnIdRef.current = null;
134	    agentBufRef.current = "";
135	    userTurnIdRef.current = null;
136	    userBufRef.current = "";
137	    inputRmsRef.current = 0;
138	  }, []);
139	
140	  const send = useCallback((obj: unknown) => {
141	    const ws = wsRef.current;
142	    if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(obj));
143	  }, []);
144	
145	  const start = useCallback(() => {
146	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
147	    endedRef.current = false;
148	    streamingRef.current = false;
149	    setTurns([]);
150	    setCallState("connecting");
151	    setCaption("establishing session…");
152	
153	    const fail = (msg: string) => {
154	      endedRef.current = true;
155	      teardown();
156	      setCallState("ended");
157	      setCaption(msg);
158	    };
159	
160	    // 1) Bring up audio + mic capture IMMEDIATELY, in parallel with the token
161	    //    mint + WS connect. The native AudioContext rate is declared to Gemini
162	    //    in the audio MIME type ("any sample rate can be sent" — Google
163	    //    resamples to 16 kHz), so no client-side resampling is needed. Early
164	    //    PCM is buffered (earlyBufRef) until `setupComplete`, then flushed —
165	    //    so the first words spoken right after CALL aren't lost.
166	    const ctx = new AudioContext();
167	    ctxRef.current = ctx;
168	    const rate = ctx.sampleRate;
169	    playbackRef.current = new PlaybackQueue(ctx, OUTPUT_RATE);
170	    earlyBufRef.current = new EarlyAudioBuffer();
171	
172	    const chunkSize = Math.floor((rate * CHUNK_MS) / 1000);
173	    const inputMime = `audio/pcm;rate=${rate}`;
174	
175	    const startCapture = async () => {
176	      try {
177	        const stream = await navigator.mediaDevices.getUserMedia({
178	          audio: {
179	            channelCount: 1,
180	            echoCancellation: true,
181	            noiseSuppression: true,
182	            autoGainControl: true,
183	          },
184	        });
185	        if (endedRef.current) {
186	          // Hung up (or failed) while the mic prompt was open.
187	          stream.getTracks().forEach((t) => t.stop());
188	          return;
189	        }
190	        streamRef.current = stream;
191	        if (ctx.state === "suspended") await ctx.resume();
192	        const capture = await createMicCapture(ctx, stream, chunkSize, (chunk) => {
193	          inputRmsRef.current = mutedRef.current ? 0 : calculateRms(chunk);
194	          if (mutedRef.current) return;
195	          const audio = float32ToPcm16Base64(chunk);
196	          // Stream live once configured; until then accumulate the early audio.
197	          if (streamingRef.current) {
198	            send({ realtimeInput: { audio: { mimeType: inputMime, data: audio } } });
199	          } else {
200	            earlyBufRef.current?.push(audio);
201	          }
202	        });
203	        if (endedRef.current) {
204	          // Hung up while the worklet module loaded.
205	          capture.stop();
206	          return;
207	        }
208	        captureRef.current = capture;
209	      } catch {
210	        fail("— microphone permission denied —");
211	      }
212	    };
213	
214	    // Kick capture off now — do not await it, and do not wait for the WS.
215	    void startCapture();
216	
217	    void (async () => {
218	      // 2) Mint the single-use ephemeral token server-side (in parallel with capture).
219	      let token: string | null = null;
220	      try {
221	        const res = await fetch("/api/gemini/token", { method: "POST" });
222	        const data = await res.json();
223	        if (!res.ok) {
224	          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
225	          return;
226	        }
227	        if (typeof data?.token === "string") token = data.token;
228	      } catch {
229	        fail("— could not reach token endpoint —");
230	        return;
231	      }
232	      if (!token) {
233	        fail("— no Gemini token returned —");
234	        return;
235	      }
236	      if (endedRef.current) return; // hung up (or mic denied) during fetch
237	
238	      // ── transcript helpers ──────────────────────────────────────────────
239	      // The setTurns updaters must stay PURE (no ref mutation inside): React
240	      // StrictMode double-invokes them, so any id/sequence mutation happens here
241	      // once, before calling setTurns.
242	      const pushAgentDelta = (delta: string) => {
243	        agentBufRef.current += delta;
244	        const text = agentBufRef.current;
245	        setCaption(text);
246	        let id = agentTurnIdRef.current;
247	        if (id) {
248	          const tid = id;
249	          setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
250	        } else {
251	          id = `g${turnSeqRef.current++}`;
252	          agentTurnIdRef.current = id;
253	          const tid = id;
254	          setTurns((prev) => [...prev, { id: tid, who: "agent", text, live: true }]);
255	        }
256	      };
257	      const finalizeAgent = () => {
258	        const id = agentTurnIdRef.current;
259	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
260	        agentTurnIdRef.current = null;
261	        agentBufRef.current = "";
262	      };
263	      // User speech streams in as inputTranscription fragments — accumulate a
264	      // live turn and finalize it once the model starts (or completes) a reply.
265	      const pushUserDelta = (delta: string) => {
266	        userBufRef.current += delta;
267	        const text = userBufRef.current;
268	        setCaption(text);
269	        let id = userTurnIdRef.current;
270	        if (id) {
271	          const tid = id;
272	          setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
273	        } else {
274	          id = `g${turnSeqRef.current++}`;
275	          userTurnIdRef.current = id;
276	          const tid = id;
277	          setTurns((prev) => [...prev, { id: tid, who: "user", text, live: true }]);
278	        }
279	      };
280	      const finalizeUser = () => {
281	        const id = userTurnIdRef.current;
282	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
283	        userTurnIdRef.current = null;
284	        userBufRef.current = "";
285	      };
286	
287	      // 3) Resolve the active persona's agent config, then open the WS
288	      //    (the ephemeral token rides the access_token query param).
289	      const agent = resolveGeminiAgent(personaRef.current?.id);
290	      const ws = new WebSocket(`${REALTIME_URL}?access_token=REDACTED;
291	      wsRef.current = ws;
292	
293	      ws.onopen = () => {
294	        if (endedRef.current) return;
295	        // First message MUST be setup; the session is live on `setupComplete`.
296	        send({
297	          setup: {
298	            model: `models/${agent.model}`,
299	            generationConfig: {
300	              responseModalities: ["AUDIO"],
301	              speechConfig: {
302	                voiceConfig: { prebuiltVoiceConfig: { voiceName: agent.voice } },
303	              },
304	            },
305	            systemInstruction: { parts: [{ text: agent.instructions }] },
306	            realtimeInputConfig: {
307	              automaticActivityDetection: { ...agent.activityDetection },
308	            },
309	            inputAudioTranscription: {},
